/**
 * Concatenate the browser-half fragments into the single ModuleLoader bundle
 * `client.js`.
 *
 * Fragment sources (all share one factory scope, joined in dependency order):
 *   - `src/client/NN-*.js`           hand-written fragments
 *   - `src/client/generated/NN-*.js` files generated by the `build-*.mjs` scripts
 *
 * `NN` is the two-digit layer prefix: every fragment may only reference symbols
 * declared by a fragment with a smaller prefix (enforced by
 * `scripts/check-architecture.mjs`). Prefixes are unique across both
 * directories. Fragments must not use `import`/`export`; React arrives through
 * the factory's `require`.
 *
 * Usage:
 *   node scripts/build-client.mjs            rebuild client.js
 *   node scripts/build-client.mjs --check    fail (without writing) when client.js is stale
 */
import { promises as fs } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
const sourceDir = path.join(root, 'src', 'client')
const generatedDir = path.join(sourceDir, 'generated')
const target = path.join(root, 'client.js')
const CHECK_ONLY = process.argv.includes('--check')

/** One layer of fragments: `{ prefix, name, rel, dir }`, sorted by prefix. */
async function collectFragments(dir, relBase) {
  let names
  try {
    names = await fs.readdir(dir)
  } catch (error) {
    if (error.code === 'ENOENT') return []
    throw error
  }
  return names
    .filter((name) => /^\d{2}-[\w.-]+\.js$/.test(name))
    .map((name) => ({
      prefix: name.slice(0, 2),
      name,
      rel: `${relBase}${name}`,
      dir,
    }))
}

const fragments = [
  ...await collectFragments(sourceDir, ''),
  ...await collectFragments(generatedDir, 'generated/'),
].sort((left, right) => left.prefix.localeCompare(right.prefix) || left.rel.localeCompare(right.rel))

if (fragments.length === 0) {
  console.error('build-client: no fragments found in src/client')
  process.exit(1)
}

const seenPrefixes = new Map()
for (const fragment of fragments) {
  const previous = seenPrefixes.get(fragment.prefix)
  if (previous !== undefined) {
    console.error(`build-client: duplicate layer prefix ${fragment.prefix} in ${previous} and ${fragment.rel}`)
    process.exit(1)
  }
  seenPrefixes.set(fragment.prefix, fragment.rel)
}

const parts = []
for (const fragment of fragments) {
  const text = await fs.readFile(path.join(fragment.dir, fragment.name), 'utf8')
  if (/^\s*(import|export)\s/m.test(text)) {
    console.error(`build-client: ${fragment.rel} must not use import/export inside the factory scope`)
    process.exit(1)
  }
  parts.push(`  // ---------------------------------------------------------------------\n  // ${fragment.rel}\n  // ---------------------------------------------------------------------\n${text.trimEnd()}`)
}
const body = parts.join('\n\n')

const bundle = `/**
 * Browser half of dsh-nce — generated by scripts/build-client.mjs from
 * src/client/*.js (hand-written fragments) and src/client/generated/*.js
 * (generated data). Do not edit this file by hand.
 *
 * Registers the "NCE" sidebar entry and the learning panel: course list,
 * per-lesson tabs, exercise papers, SRS word cards, review queue, IPA/phonics.
 * React comes from the browser module table; every color is a host
 * \`--dsw-alias-*\` theme token.
 */
window.__ModuleLoader__.load({
  id: 'dsh-nce',
  factory(require) {
${body}
  },
})
`

// Parse without executing: a syntax error fails here instead of blanking the slot.
try {
  new Function(`return function factory(require) {\n${body}\n}`)
} catch (error) {
  console.error(`build-client: syntax error in fragments: ${error.message}`)
  process.exit(1)
}

if (CHECK_ONLY) {
  const current = await fs.readFile(target, 'utf8').catch(() => '')
  if (current !== bundle) {
    console.error('build-client: client.js is stale — run node scripts/build-client.mjs')
    process.exit(1)
  }
  console.log(`build-client: up to date (${fragments.length} fragments)`)
} else {
  await fs.writeFile(target, bundle, 'utf8')
  const bytes = Buffer.byteLength(bundle)
  console.log(`build-client: wrote client.js (${fragments.length} fragments, ${(bytes / 1024).toFixed(1)} KiB)`)
}
